    cursor: not-allowed;
}

input[aria-invalid="true"] {
    border-color: #e53e3e;
}

input[aria-invalid="true"]:focus {
    box-shadow: 0 0 0 3px rgba(229, 62, 62, 0.1);
}

.help-text {
    font-size: 0.85rem;
    color: #718096;
    line-height: 1.5;
    margin: 0;
}

.error-message {
    font-size: 0.85rem;
    color: #e53e3e;
    line-height: 1.5;
    margin: 0;
    min-height: 1.2rem;
    display: none;
}

.error-message.show {
    display: block;
}

.submit-button {
    padding: 0.875rem 1.5rem;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 1rem;
}

.submit-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 20px rgba(102, 126, 234, 0.3);
}

.submit-button:active {
    transform: translateY(0);
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.5);
}

.success-message {
    padding: 1rem;
    background-color: #c6f6d5;
    border: 2px solid #9ae6b4;
    border-radius: 8px;
    color: #22543d;
    font-weight: 600;
    text-align: center;
    margin-top: 1rem;
