+class ContactForm {
+    constructor(formId) {
+        this.form = document.getElementById(formId);
+        this.fullNameField = document.getElementById('fullName');
+        this.emailField = document.getElementById('email');
+        this.phoneField = document.getElementById('phone');
+        this.successMessage = document.getElementById('successMessage');
+
+        this.validators = {
+            fullName: this.validateFullName.bind(this),
+            email: this.validateEmail.bind(this),
+            phone: this.validatePhone.bind(this),
+        };
+
+        this.init();
+    }
+
+    init() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        
+        this.fullNameField.addEventListener('blur', () => this.validateAndDisplay('fullName'));
+        this.emailField.addEventListener('blur', () => this.validateAndDisplay('email'));
+        this.phoneField.addEventListener('blur', () => this.validateAndDisplay('phone'));
+
+        this.fullNameField.addEventListener('input', () => {
+            if (this.fullNameField.getAttribute('aria-invalid') === 'true') {
+                this.validateAndDisplay('fullName');
+            }
+        });
+
+        this.emailField.addEventListener('input', () => {
+            if (this.emailField.getAttribute('aria-invalid') === 'true') {
+                this.validateAndDisplay('email');
+            }
+        });
+
+        this.phoneField.addEventListener('input', () => {
+            if (this.phoneField.getAttribute('aria-invalid') === 'true') {
+                this.validateAndDisplay('phone');
+            }
+        });
+    }
+
+    validateFullName() {
+        const value = this.fullNameField.value.trim();
+
+        if (!value) {
+            return 'Error: Full name is required.';
+        }
+
+        if (value.length < 2) {
+            return 'Error: Full name must be at least 2 characters.';
+        }
+
+        return '';
+    }
+
+    validateEmail() {
+        const value = this.emailField.value.trim();
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+        if (!value) {
+            return 'Error: Email address is required.';
+        }
+
+        if (!emailRegex.test(value)) {
+            return 'Error: Enter a valid email like name@example.com.';
+        }
+
+        return '';
+    }
+
+    validatePhone() {
+        const value = this.phoneField.value.trim();
+
+        if (!value) {
+            return '';
+        }
+
+        const phoneRegex = /^(\+?1[-.\s]?)?\(?([0-9]{3})\)?[-.\s]?([0-9]{3})[-.\s]?([0-9]{4})$/;
+
+        if (!phoneRegex.test(value)) {
+            return 'Error: Enter a valid phone number like (123) 456-7890.';
+        }
+
+        return '';
+    }
+
+    validateAndDisplay(fieldName) {
+        const field = this[`${fieldName}Field`];
+        const errorElement = document.getElementById(`${fieldName}-error`);
+        const validator = this.validators[fieldName];
+
+        const error = validator();
+
+        if (error) {
+            field.setAttribute('aria-invalid', 'true');
+            errorElement.textContent = error;
+            errorElement.classList.add('show');
+        } else {
+            field.setAttribute('aria-invalid', 'false');
+            errorElement.textContent = '';
+            errorElement.classList.remove('show');
+        }
+    }
+
+    validateAll() {
+        const errors = {
+            fullName: this.validateFullName(),
+            email: this.validateEmail(),
+            phone: this.validatePhone(),
+        };
+
+        let firstInvalidField = null;
+
+        Object.entries(errors).forEach(([fieldName, error]) => {
+            const field = this[`${fieldName}Field`];
+            const errorElement = document.getElementById(`${fieldName}-error`);
+
+            if (error) {
+                field.setAttribute('aria-invalid', 'true');
+                errorElement.textContent = error;
+                errorElement.classList.add('show');
+
+                if (!firstInvalidField) {
+                    firstInvalidField = field;
+                }
+            } else {
+                field.setAttribute('aria-invalid', 'false');
+                errorElement.textContent = '';
+                errorElement.classList.remove('show');
+            }
+        });
+
+        return { isValid: !firstInvalidField, firstInvalidField };
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+        this.successMessage.classList.remove('show');
+
+        const { isValid, firstInvalidField } = this.validateAll();
+
+        if (!isValid) {
+            firstInvalidField.focus();
+            return;
+        }
+
+        const formData = {
+            fullName: this.fullNameField.value.trim(),
+            email: this.emailField.value.trim(),
+            phone: this.phoneField.value.trim(),
+        };
+
+        this.successMessage.textContent = '✓ Thank you! Your message has been sent successfully.';
+        this.successMessage.classList.add('show');
+
+        console.log('Form submitted:', formData);
+
+        this.form.reset();
+        this.fullNameField.setAttribute('aria-invalid', 'false');
+        this.emailField.setAttribute('aria-invalid', 'false');
+        this.phoneField.setAttribute('aria-invalid', 'false');
+
+        setTimeout(() => {
+            this.successMessage.classList.remove('show');
+        }, 5000);
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm('contactForm');
+});
+
")

