+  const browser = await chromium.launch();
+  const page = await browser.newPage();
+  
+  const htmlPath = path.join(__dirname, 'index.html');
+  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');
+  
+  await page.setContent(htmlContent, { waitUntil: 'load' });
+  
+  // Inject axe-core
+  await page.addScriptTag({
+    path: require.resolve('axe-core/axe.min.js')
+  });
+  
+  // Test 1: Initial state
+  console.log('=== Test 1: Initial state ===');
+  let results = await page.evaluate(async () => {
+    return await window.axe.run();
+  });
+  
+  let wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
+  console.log(`Initial state - WCAG violations: ${wcagViolations.length}`);
+  if (wcagViolations.length > 0) {
+    wcagViolations.forEach(v => console.log(`  - ${v.id}: ${v.description}`));
+  }
+  
+  // Test 2: Interact with form - fill invalid data and trigger validation
+  console.log('\n=== Test 2: After validation attempt (invalid data) ===');
+  
+  // Fill in invalid email
+  await page.fill('#email', 'invalid-email');
+  await page.click('#fullName'); // trigger blur on email
+  
+  // Wait for validation message to appear
+  await page.waitForTimeout(100);
+  
+  results = await page.evaluate(async () => {
+    return await window.axe.run();
+  });
+  
+  wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
+  console.log(`After invalid input - WCAG violations: ${wcagViolations.length}`);
+  if (wcagViolations.length > 0) {
+    wcagViolations.forEach(v => console.log(`  - ${v.id}: ${v.description}`));
+  }
+  
+  // Test 3: Fill form correctly
+  console.log('\n=== Test 3: After valid input ===');
+  await page.fill('#fullName', 'John Doe');
+  await page.fill('#email', 'john@example.com');
+  await page.fill('#phone', '(555) 123-4567');
+  
+  // Trigger blur events
+  await page.evaluate(() => {
+    document.getElementById('fullName').blur();
+    document.getElementById('email').blur();
+    document.getElementById('phone').blur();
+  });
+  
+  await page.waitForTimeout(100);
+  
+  results = await page.evaluate(async () => {
+    return await window.axe.run();
+  });
+  
+  wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
+  console.log(`After valid input - WCAG violations: ${wcagViolations.length}`);
+  if (wcagViolations.length > 0) {
+    wcagViolations.forEach(v => console.log(`  - ${v.id}: ${v.description}`));
+  }
+  
+  // Test 4: Keyboard navigation
+  console.log('\n=== Test 4: Keyboard focus (Tab through fields) ===');
+  await page.reload();
+  await page.waitForLoadState('load');
+  
