+  await page.addScriptTag({
+    path: require.resolve('axe-core/axe.min.js')
+  });
+  
+  // Tab through fields
+  await page.keyboard.press('Tab'); // Focus first input
+  await page.keyboard.press('Tab'); // Focus second input
+  await page.keyboard.press('Tab'); // Focus third input
+  
+  results = await page.evaluate(async () => {
+    return await window.axe.run();
+  });
+  
+  wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
+  console.log(`After keyboard navigation - WCAG violations: ${wcagViolations.length}`);
+  if (wcagViolations.length > 0) {
+    wcagViolations.forEach(v => console.log(`  - ${v.id}: ${v.description}`));
